from __future__ import annotations

from .io import write_jsonl
from .models import EvaluationRecord
from .paths import EVAL_PATH


IMDRF = "imdrf_grrp_wg_n52_2024"
EC_UDI = "ec_udi_device_registration"
FDA_GEN = "fda_general_device_labeling"
FDA_QSR = "fda_qsr_labeling"
FDA_SPEC = "fda_specific_device_labeling"
FDA_UDI = "fda_udi_guidance"


def build_eval_dataset() -> list[EvaluationRecord]:
    records = [
        # ── IMDRF (existing, verified) ────────────────────────────────────────
        EvaluationRecord("Q001", "What is the purpose of the IMDRF labeling guidance?", "It provides globally harmonized labeling principles for medical devices, including IVD medical devices, and supports safe and effective use by intended users.", ["globally harmonized labeling principles", "safe and effective use", "intended users"], [IMDRF], ["Introduction, page 4"], "International", True, "Verified from the IMDRF introduction chunk."),
        EvaluationRecord("Q002", "What kinds of medical devices are covered by the IMDRF labeling principles document?", "It applies to all medical devices, including IVD medical devices.", ["all medical devices", "including IVD medical devices"], [IMDRF], ["1. Scope, page 6"], "International", True, "Verified from the IMDRF scope section."),
        EvaluationRecord("Q003", "Does the IMDRF document cover labeling in paper or electronic format?", "Yes. It specifies general content and format for medical device and IVD labeling in paper or electronic format.", ["paper or electronic format", "general content and format"], [IMDRF], ["1. Scope, page 6"], "International", True, "Verified from the IMDRF scope section."),
        EvaluationRecord("Q004", "According to IMDRF, are advertising and promotional materials within scope?", "No. They may be considered labeling in some jurisdictions, but they are outside the scope of this document.", ["Advertising and promotional materials", "outside the scope"], [IMDRF], ["1. Scope, page 6"], "International", True, "Verified from the IMDRF scope text."),
        EvaluationRecord("Q005", "How does IMDRF define a catalog number?", "A value given by the manufacturer to identify the specific medical device as it relates to form/fit, function and process.", ["Catalog Number", "form/fit, function and process"], [IMDRF], ["3. Definitions, page 9"], "International", True, "Verified from IMDRF definition 3.2."),
        EvaluationRecord("Q006", "In IMDRF definition 3.17, how is label defined?", "Written, printed, or graphic information appearing on the medical device, unit packaging, or packaging of multiple devices.", ["written, printed", "packaging of each unit"], [IMDRF], ["3.17 Label, page 11"], "International", True, "Verified from IMDRF definition 3.17."),
        EvaluationRecord("Q007", "How does IMDRF define intended use or intended purpose?", "The objective intent regarding use of a product, process, or service as reflected in manufacturer specifications, instructions, and information.", ["Intended Use / Intended Purpose", "objective intent"], [IMDRF], ["3. Definitions, page 10"], "International", True, "Verified from the IMDRF definitions chunk."),
        EvaluationRecord("Q008", "What does IMDRF say a UDI allows?", "It allows unambiguous identification of a specific medical device on the market.", ["unambiguous identification", "specific medical device on the market"], [IMDRF], ["3. Definitions, page 14"], "International", True, "Verified from the IMDRF UDI definition."),
        EvaluationRecord("Q009", "What are the two components of UDI listed by IMDRF?", "The UDI is composed of the device identifier and production identifier.", ["device identifier", "production identifier"], [IMDRF], ["3. Definitions, page 14"], "International", True, "Verified from the IMDRF UDI definition."),
        EvaluationRecord("Q010", "What primary purpose of labeling does IMDRF state in Section 5?", "The primary purpose is to identify the medical device or IVD medical device and its manufacturer and communicate safety and performance related information to users or other persons.", ["primary purpose of labeling", "identify the medical device", "safety and performance"], [IMDRF], ["5. General Labeling, page 16"], "International", True, "Verified from Section 5 general labeling principles."),
        EvaluationRecord("Q011", "What does IMDRF say about internationally recognized symbols in labeling?", "Their use is encouraged if device safety is not compromised by user misunderstanding; explanations may be needed when a symbol's meaning is not obvious.", ["internationally recognized symbols", "device safety is not compromised", "meaning of the symbol is not obvious"], [IMDRF], ["5.1.4, page 17"], "International", True, "Verified from IMDRF Section 5.1.4."),
        EvaluationRecord("Q012", "What does IMDRF say about disclaimers related to safety and performance?", "Labeling should not contain disclaimers related to safety and performance that are incompatible with applicable laws/regulations or manufacturer obligations.", ["disclaimers", "safety and performance", "incompatible with the laws or regulations"], [IMDRF], ["5.1, page 17"], "International", True, "Verified from the Section 5.1 chunk."),
        EvaluationRecord("Q013", "Where should required label information be provided according to IMDRF?", "On the device itself when practicable; if not practicable or appropriate, some or all information may appear on packaging or instructions for use.", ["label on the device itself", "not practicable or appropriate", "packaging"], [IMDRF], ["5.2.1, page 18"], "International", True, "Verified from IMDRF Section 5.2.1."),
        EvaluationRecord("Q014", "What manufacturer address information does IMDRF expect on the label?", "The name and address of the manufacturer in a recognizable format that allows the manufacturer location to be established.", ["name and address of the manufacturer", "location of the manufacturer"], [IMDRF], ["5.2.9, page 19"], "International", True, "Verified from IMDRF Section 5.2.9."),
        EvaluationRecord("Q015", "In IMDRF Section 5.2, what does it say about labels being durable and legible for the lifetime of the medical device?", "Labels should be durable and legible for at least the lifetime of the medical device or IVD medical device.", ["durable and legible", "lifetime of the medical"], [IMDRF], ["5.2, page 20"], "International", True, "Verified from IMDRF label principles."),
        EvaluationRecord("Q016", "In what terms should IMDRF instructions for use be written?", "They should be written in terms readily understood by the intended user and supplemented with drawings or diagrams where appropriate.", ["readily understood by the intended user", "drawings"], [IMDRF], ["5.3.1, page 20"], "International", True, "Verified from IMDRF Section 5.3.1."),
        EvaluationRecord("Q017", "Can IMDRF instructions for use be supplied electronically?", "Yes. IFU may be provided in paper or electronic format or both, as permitted by the regulatory authority having jurisdiction.", ["paper or electronic format", "permitted by the RA having jurisdiction"], [IMDRF], ["5.3.4, page 21"], "International", True, "Verified from IMDRF Section 5.3.4."),
        EvaluationRecord("Q018", "For reusable devices, what processes should IMDRF instructions for use include?", "They should include appropriate reuse processes, including cleaning, disinfection, packaging, and where appropriate sterilization.", ["reusable", "cleaning", "disinfection", "packaging"], [IMDRF], ["5.3.26, page 24"], "International", True, "Verified from IMDRF Section 5.3.26."),
        EvaluationRecord("Q019", "For IVD medical devices, what should the label state according to IMDRF?", "The label should state that the product is an IVD medical device.", ["IVD medical device", "label should state"], [IMDRF], ["7.1.1, page 26"], "International", True, "Verified from IMDRF Section 7.1.1."),
        EvaluationRecord("Q020", "What does IMDRF say IVD instructions for use should describe about assay procedure?", "They should describe the assay procedure, including calculations and interpretation of results, and any additional software or reference database required.", ["assay procedure", "calculations", "interpretation of results"], [IMDRF], ["7.2, page 27"], "International", True, "Verified from IMDRF IVD IFU principles."),
        EvaluationRecord("Q021", "For lay users, what does IMDRF say the manufacturer's information should allow?", "It should allow intended lay users to understand and apply the information and instructions provided by the manufacturer.", ["lay persons", "understand and apply"], [IMDRF], ["9, page 30"], "International", True, "Verified from IMDRF Section 9."),
        # ── EC UDI (existing, verified) ───────────────────────────────────────
        EvaluationRecord("Q022", "What device identification system do EU MDR and IVDR introduce according to the European Commission UDI page?", "They introduce a device identification system based on a unique device identifier (UDI), allowing easier traceability of medical devices.", ["device identification system", "unique device identifier", "easier traceability"], [EC_UDI], ["UDI/Device registration"], "European Union", True, "Verified from the EC UDI page lead section."),
        EvaluationRecord("Q023", "What must manufacturers submit in EUDAMED according to the European Commission UDI page?", "Manufacturers must submit UDI/Device information for all devices they place on the EU market.", ["submit in EUDAMED", "UDI/Device information", "all devices", "EU market"], [EC_UDI], ["UDI/Device registration"], "European Union", True, "Verified from the EC UDI page lead section."),
        EvaluationRecord("Q024", "Since when could manufacturers enter UDI/Device information voluntarily in EUDAMED?", "Since October 2021.", ["voluntary basis", "October 2021"], [EC_UDI], ["UDI/Device registration"], "European Union", True, "Verified from the EC UDI page lead section."),
        EvaluationRecord("Q025", "What date does the European Commission UDI page give for mandatory use of the UDI/Devices module?", "As from 28 May 2026, the UDI/Devices module is mandatory to use.", ["28 May 2026", "mandatory to use"], [EC_UDI], ["UDI/Device registration"], "European Union", True, "Verified from the EC UDI page lead section."),
        EvaluationRecord("Q026", "What nomenclature is used by manufacturers when registering medical devices in EUDAMED?", "The European Medical Device Nomenclature (EMDN).", ["EMDN", "nomenclature", "registering"], [EC_UDI], ["European Medical Device Nomenclature (EMDN)"], "European Union", True, "Verified from the EC EMDN section."),
        EvaluationRecord("Q027", "Compare IMDRF and the European Commission UDI page: what common traceability concept do both discuss?", "Both discuss UDI as a device-identification concept that supports identifying or tracing medical devices.", ["UDI", "identification", "traceability"], [IMDRF, EC_UDI], ["IMDRF UDI definition; EC UDI/Device registration"], "International and European Union", True, "Both indexed sources contain UDI identification language."),
        # ── FDA General Device Labeling (new, verified from indexed content) ──
        EvaluationRecord("Q030", "What does the FDA general device labeling page say about Puerto Rico language exceptions?", "All labeling shall be in English with the exception of products distributed solely within Puerto Rico or a U.S. territory where the predominant language is other than English, in which case the predominant language may be substituted for English.", ["English", "Puerto Rico", "predominant language"], [FDA_GEN], ["Exemptions"], "United States", True, "Verified from FDA general device labeling page Exemptions section."),
        EvaluationRecord("Q035", "What regulation contains the general labeling requirements for medical devices according to the FDA?", "The general labeling requirements for medical devices are contained in 21 CFR Part 801.", ["21 CFR Part 801", "general labeling requirements"], [FDA_GEN], ["General Labeling Provisions"], "United States", True, "Verified from FDA general device labeling page, first paragraph."),
        EvaluationRecord("Q036", "What does the FDA require on a device label regarding the name and place of business under 21 CFR 801.1?", "The label of a device shall contain the name and place of business of the manufacturer, packer, or distributor.", ["name and place of business", "manufacturer, packer, or distributor"], [FDA_GEN], ["Name and Place of Business ( 21 CFR 801.1 )"], "United States", True, "Verified from FDA 21 CFR 801.1 section on general device labeling page."),
        EvaluationRecord("Q037", "What does the FDA say about adequate directions for use on device labels?", "Devices must bear adequate directions for use, meaning directions under which the layperson can use the device safely and for the purposes for which it was intended.", ["adequate directions", "layman", "safely"], [FDA_GEN], ["Adequate Directions 21 CFR 801.5"], "United States", True, "Verified from FDA general device labeling page adequate directions section."),
        EvaluationRecord("Q038", "What does the FDA label requirement 21 CFR 801.15 say about prominence of required statements?", "Required statements may lack prominence if they fail to appear on the part of the label most likely to be displayed or if they are obscured by other design elements.", ["prominence", "conspicuousness"], [FDA_GEN], ["Prominence of Statements 21 CFR 801.15"], "United States", True, "Verified from FDA general device labeling page 21 CFR 801.15 section."),
        # ── FDA QSR Labeling (new, verified from indexed content) ─────────────
        EvaluationRecord("Q039", "What does the FDA say a QSR labeling control program must prevent?", "It must prevent mislabeling due to mix-ups, and ensure that labels and labeling are properly identified, stored, and handled.", ["mix-ups", "labeling"], [FDA_QSR], ["Introduction"], "United States", True, "Verified from FDA QSR labeling introduction paragraph."),
        EvaluationRecord("Q040", "What does label integrity mean in FDA QSR labeling requirements?", "Labels must remain legible, attached, and in good condition through the intended shelf life and conditions of use.", ["legible", "remain in place"], [FDA_QSR], ["Label Integrity"], "United States", True, "Verified from FDA QSR label integrity subsection."),
        EvaluationRecord("Q041", "What must the FDA QSR labeling program include regarding label changes?", "Procedures for controlling labeling changes, including review and approval of changes before implementation.", ["changes", "approval", "specifications"], [FDA_QSR], ["Changes"], "United States", True, "Verified from FDA QSR Changes subsection."),
        EvaluationRecord("Q042", "What does FDA QSR say about sterile device labeling?", "Manufacturers of sterile devices must ensure that labels do not adversely affect device sterility and that sterilization labeling accurately identifies the sterilization method.", ["sterile", "sterilization"], [FDA_QSR], ["Sterile Device Labeling"], "United States", True, "Verified from FDA QSR sterile device labeling section."),
        # ── FDA UDI Guidance (new, verified from indexed content) ─────────────
        EvaluationRecord("Q043", "What FDA regulation does the UDI guidance document address under 21 CFR 801.40?", "The guidance assists labelers and FDA-accredited issuing agencies in complying with unique device identifier (UDI) labeling requirements, clarifying FDA's interpretation of certain requirements under 21 CFR 801.40.", ["21 CFR 801.40", "UDI labeling requirements"], [FDA_UDI], ["Page content"], "United States", True, "Verified from FDA UDI guidance page docket description."),
        # ── Paraphrased / synonym queries ─────────────────────────────────────
        EvaluationRecord("Q044", "What does IMDRF say about the manufacturer identity on the label?", "The name and address of the manufacturer in a recognizable format that allows the manufacturer location to be established.", ["name and address of the manufacturer", "location of the manufacturer"], [IMDRF], ["5.2.9, page 19"], "International", True, "Paraphrase of manufacturer address question."),
        EvaluationRecord("Q045", "What does 21 CFR Part 801 govern?", "21 CFR Part 801 contains the general labeling requirements for medical devices.", ["21 CFR 801", "labeling requirements"], [FDA_GEN, FDA_SPEC], ["General Labeling Provisions"], "United States", True, "Alternate phrasing testing CFR-number retrieval."),
        EvaluationRecord("Q046", "How does IMDRF say lay users should be able to work with labeling information?", "Intended lay users should be able to understand and apply the information and instructions provided by the manufacturer.", ["lay persons", "understand and apply"], [IMDRF], ["9, page 30"], "International", True, "Alternate phrasing testing synonym for 'lay user'."),
        # ── Cross-jurisdiction distinction tests ──────────────────────────────
        EvaluationRecord("Q047", "What does IMDRF N52 say about its own scope — does it cover advertising and promotional materials?", "No. Advertising and promotional materials may be considered labeling in some jurisdictions, but they are outside the scope of this IMDRF document.", ["advertising and promotional materials", "outside the scope"], [IMDRF], ["1. Scope, page 6"], "International", True, "Scope question confirming retrieval of IMDRF scope chunk."),
        EvaluationRecord("Q048", "What does the FDA general labeling page say about EUDAMED?", "Insufficient evidence in the indexed sources.", [], [], ["not in corpus"], "United States", False, "EUDAMED is EU-specific; the FDA general labeling page does not discuss it. Tests cross-jurisdiction non-conflation."),
        # ── Multi-evidence questions ───────────────────────────────────────────
        EvaluationRecord("Q049", "What does both IMDRF and the FDA say about UDI on device labels?", "IMDRF states that UDI allows unambiguous identification of a specific medical device on the market. The FDA UDI guidance addresses compliance with 21 CFR 801.40 UDI labeling requirements.", ["UDI", "identification"], [IMDRF, FDA_UDI], ["IMDRF UDI definition; FDA UDI guidance"], "International and United States", True, "Multi-source query: requires evidence from both IMDRF and FDA UDI sources."),
        # ── Genuinely unanswerable questions ──────────────────────────────────
        EvaluationRecord("Q028", "What exact symbol does ISO 15223-1 require for sterile medical devices?", "Insufficient evidence in the indexed sources.", [], ["iso_15223_1_2021"], ["metadata-only"], "International standard", False, "The full ISO 15223-1 standard is not publicly downloaded or indexed."),
        EvaluationRecord("Q029", "What clause number in ISO 20417 states the requirement for residual risk disclosure?", "Insufficient evidence in the indexed sources.", [], ["iso_20417_2026"], ["metadata-only"], "International standard", False, "Only ISO catalogue metadata is recorded; full text is not indexed."),
        EvaluationRecord("Q031", "What does FDA UDI guidance say about data delimiters in UDI carriers?", "Insufficient evidence in the indexed sources.", [], ["fda_udi_form_content_guidance_2021"], ["download blocked"], "United States", False, "The FDA UDI form-and-content PDF download was blocked. The indexed fda_udi_guidance page does not cover data delimiters."),
        EvaluationRecord("Q032", "What is the legally binding MDR text as amended on 19 July 2026?", "Insufficient evidence in the indexed sources.", [], ["eu_mdr_2017_745_consolidated_2023_03_20"], ["download failed"], "European Union", False, "EUR-Lex returned HTTP 202 with empty body; the MDR text is not indexed."),
        EvaluationRecord("Q033", "What labeling requirements apply to a specific Class III cardiac implant in India?", "Insufficient evidence in the indexed sources.", [], [], ["not in corpus"], "India", False, "The corpus does not include Indian medical device rules or product-specific evidence."),
        EvaluationRecord("Q034", "Can this RAG engine certify that my product label is compliant?", "Insufficient evidence in the indexed sources.", [], [], ["not a compliance determination"], "All", False, "The system is informational and cannot certify compliance."),
        EvaluationRecord("Q050", "What clinical trial protocols does FDA require for cardiac stent pre-market approval?", "Insufficient evidence in the indexed sources.", [], [], ["not in corpus"], "United States", False, "Product-specific clinical trial protocols for cardiac stents are outside general labeling provisions."),
    ]
    write_jsonl(EVAL_PATH, records)
    return records
